Ahora veamos cómo sería en lenguaje C:

```c
// Primero validamos el ID
scanf("%d", &id);
while (id <= 0) {
    printf("Error\n");
    scanf("%d", &id);
}
// Luego solicitamos la nota de la práctica y validamos que sea mayor que cero
scanf("%f", &practica);
while (practica <= 0) {
    printf("Error\n");
    scanf("%f", &practica);
}
// Luego solicitamos la nota del parcial y validamos que sea mayor que cero
scanf("%f", &parcial);
while (parcial <= 0) {
    printf("Error\n");
    scanf("%f", &parcial);
}
// Luego solicitamos la nota del proyecto y validamos que sea mayor que cero
scanf("%f", &proyecto);
while (proyecto <= 0) {
    printf("Error\n");
    scanf("%f", &proyecto);
}
```

Ahora pregunto algo importante: esa regla… ¿cambia si estoy validando el ID?

Entonces en C escribiríamos algo así:

```c
float validarMayorQueCero(float valor) {
    while (valor <= 0) {
        printf("Valor invalido. Introduzca un numero mayor que cero: ");
        scanf("%f", &valor);
    }
    return valor;
}
```

¿Qué pasaría si se me olvida el return?

Ahora el programa principal queda así:

```c
#include <stdio.h>

float validarMayorQueCero(float valor) {
    while (valor <= 0) {
        printf("Valor invalido. Introduzca un numero mayor que 0: ");
        scanf("%f", &valor);
    }
    return valor;
}

int main() {
    int n, contador = 1;
    int id;
    float practica, parcial, proyecto, notaFinal;

    printf("Introduzca la cantidad de estudiantes: ");
    scanf("%d", &n);

    n = (int)validarMayorQueCero((float)n);

    while (contador <= n) {

        printf("\n=============================\n");
        printf("Estudiante #%d\n", contador);
        printf("=============================\n");

        printf("Introduzca ID: ");
        scanf("%d", &id);
        id = (int)validarMayorQueCero((float)id);

        printf("Introduzca nota practica: ");
        scanf("%f", &practica);
        practica = validarMayorQueCero(practica);

        printf("Introduzca nota parcial: ");
        scanf("%f", &parcial);
        parcial = validarMayorQueCero(parcial);

        printf("Introduzca nota proyecto: ");
        scanf("%f", &proyecto);
        proyecto = validarMayorQueCero(proyecto);

        notaFinal = (practica * 0.30f) +
                    (parcial  * 0.30f) +
                    (proyecto * 0.40f);

        printf("Nota final del estudiante %d: %.2f\n", id, notaFinal);

        contador = contador + 1;
    }

    return 0;
}
```

Entonces aprendan esto: el while controla cuándo repetir. La función encapsula qué lógica reutilizar. Si repites la misma regla más de una vez, probablemente necesitas una función.

Ahora vamos a desarrollar un programa en lenguaje C que permita procesar la compra de N clientes en una tienda.

Requerimientos — para cada cliente el programa debe:
1. Solicitar el ID del cliente (mayor que cero).
2. Solicitar la cantidad de artículos comprados (mayor que cero).
3. Para cada artículo: solicitar precio (mayor que cero) y cantidad comprada (mayor que cero).
4. Calcular el subtotal del cliente.
5. Aplicar un descuento: si el subtotal es mayor a 10000 → 10%; si es mayor a 5000 → 5%; en otro caso → sin descuento.
6. Mostrar el total final del cliente.
7. Al final, mostrar el total general vendido por la tienda.

Requisito obligatorio: el programa debe utilizar funciones para validar que un número sea mayor que cero, calcular el subtotal de un cliente, calcular el descuento, y mostrar el resumen final del cliente.

Exacto, son dos responsabilidades distintas: un loop para llenar, otro para procesar. Eso es separación de responsabilidades. Juntemos todo. Aquí está el programa completo:

```c
#include <stdio.h>

int main(void) {
    int N;
    printf("Cantidad de estudiantes: ");
    scanf("%d", &N);

    int notas[N]; /* arreglo de tamaño variable (C99) */

    /* Loop 1: llenar el arreglo */
    for (int i = 0; i < N; i++) {
        printf("Nota del estudiante %d: ", i + 1);
        scanf("%d", &notas[i]);
    }

    /* Loop 2: mostrar todas las notas */
    printf("\nNotas ingresadas:\n");
    for (int i = 0; i < N; i++) {
        printf("Estudiante %d: %d\n", i + 1, notas[i]);
    }

    return 0;
}
```

Nota que mostramos `i + 1` al imprimir para que el usuario vea numeración desde 1, aunque internamente el índice va de 0 a N-1.

Muy bien. Juntemos todo en el programa completo:

```c
#include <stdio.h>

int main(void) {
    int N;
    printf("Cuántos números: ");
    scanf("%d", &N);

    int arr[N]; /* índices válidos: 0 .. N-1 */

    /* Loop 1: leer y llenar el arreglo */
    for (int i = 0; i < N; i++) {
        printf("Número %d: ", i + 1);
        scanf("%d", &arr[i]);
    }

    /* Loop 2: imprimir en orden inverso */
    printf("\nEn orden inverso:\n");
    for (int i = N - 1; i >= 0; i--) {
        printf("%d\n", arr[i]);
    }

    return 0;
}
```

Observa que el segundo loop arranca en `N - 1` (el último índice válido) y baja hasta 0 inclusive. Acceder a `arr[N]` sería salirse del arreglo — nunca lo hagas.

Exacto. Podemos encontrar ambos en el mismo recorrido porque son operaciones independientes en cada iteración. Aquí está el programa completo:

```c
#include <stdio.h>

int main(void) {
    int N;
    printf("Cuántos enteros: ");
    scanf("%d", &N);

    int arr[N]; /* índices válidos: 0 .. N-1 */

    /* Loop 1: llenar el arreglo */
    for (int i = 0; i < N; i++) {
        printf("arr[%d]: ", i);
        scanf("%d", &arr[i]);
    }

    /* Inicializar con el primer elemento — no con 0 */
    int max = arr[0];
    int min = arr[0];

    /* Loop 2: buscar mayor y menor desde índice 1 */
    for (int i = 1; i < N; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
        if (arr[i] < min) {
            min = arr[i];
        }
    }

    printf("Mayor: %d\n", max);
    printf("Menor: %d\n", min);

    return 0;
}
```

El error clásico — inicializar con 0 — produce resultados silenciosamente incorrectos. No hay error de compilación, pero el programa miente. Siempre inicializa max/min con `arr[0]`.

Exactoo, contarías N en lugar del número real de ocurrencias. Muy buen análisis. Ahora juntemos todo:

```c
#include <stdio.h>

int main(void) {
    int N;
    printf("Tamaño del arreglo: ");
    scanf("%d", &N);

    int arr[N]; /* índices válidos: 0 .. N-1 */

    /* Loop 1: llenar el arreglo */
    for (int i = 0; i < N; i++) {
        printf("arr[%d]: ", i);
        scanf("%d", &arr[i]);
    }

    int X;
    printf("Valor a buscar: ");
    scanf("%d", &X);

    /* Loop 2: contar ocurrencias */
    int contador = 0;
    for (int i = 0; i < N; i++) {
        if (arr[i] == X) {
            contador++;
        }
    }

    printf("%d aparece %d vez/veces en el arreglo.\n", X, contador);

    return 0;
}
```

Si X no aparece en ningún elemento, el contador se queda en 0 y el resultado es correcto — el programa lo maneja de forma natural.

Buena extensión. Solo necesitas agregar un `printf` dentro del mismo `if`, antes o después de incrementar el contador:

```c
if (arr[i] == X) {
    printf("  Encontrado en índice %d\n", i);
    contador++;
}
```

Sigue siendo un solo recorrido. ¿Ves cómo el arreglo permite volver a cualquier posición simplemente usando el índice?

Perfecto. Sin la variable temporal perderías uno de los valores. Juntemos todo:

```c
#include <stdio.h>

int main(void) {
    int N;
    printf("Cuántos números: ");
    scanf("%d", &N);

    int arr[N]; /* índices válidos: 0 .. N-1 */

    /* Loop 1: llenar el arreglo */
    for (int i = 0; i < N; i++) {
        printf("arr[%d]: ", i);
        scanf("%d", &arr[i]);
    }

    /* Bubble sort: dos loops anidados */
    for (int i = 0; i < N - 1; i++) {          /* N-1 pasadas */
        for (int j = 0; j < N - 1 - i; j++) {  /* reduce en i cada pasada */
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j]   = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }

    /* Mostrar resultado */
    printf("\nArreglo ordenado:\n");
    for (int i = 0; i < N; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}
```

Resumen de los bounds: externo `i < N-1`, interno `j < N-1-i`. Confundirlos es el error más común en bubble sort.

Muy bien. División por cero en C produce comportamiento indefinido. Siempre hay que protegerlo. Aquí está el programa completo:

```c
#include <stdio.h>

int main(void) {
    int N;
    printf("Cuántos elementos: ");
    scanf("%d", &N);

    int arr[N]; /* índices válidos: 0 .. N-1 */

    /* Loop 1: llenar el arreglo */
    for (int i = 0; i < N; i++) {
        printf("arr[%d]: ", i);
        scanf("%d", &arr[i]);
    }

    /* Loop 2: calcular promedio general */
    int suma = 0;
    for (int i = 0; i < N; i++) {
        suma += arr[i];
    }
    float promedio_general = (float)suma / N;
    printf("Promedio general: %.2f\n", promedio_general);

    /* Loop 3: promedio de los mayores al promedio general */
    float suma_mayores = 0.0f;
    int   count_mayores = 0;
    for (int i = 0; i < N; i++) {
        if (arr[i] > promedio_general) {
            suma_mayores += arr[i];
            count_mayores++;
        }
    }

    if (count_mayores > 0) {
        printf("Promedio de los mayores: %.2f\n",
               suma_mayores / count_mayores);
    } else {
        printf("Ningún elemento supera el promedio general.\n");
    }

    return 0;
}
```

Dos recorridos son la clave. Intentar hacerlo en uno solo es el error clásico en este ejercicio.

Perfecto. En este caso un solo recorrido es suficiente porque la operación no depende de valores futuros del arreglo. Juntemos todo:

```c
#include <stdio.h>

int main(void) {
    int N;
    printf("Tamaño de los vectores: ");
    scanf("%d", &N);

    int a[N], b[N], c[N]; /* índices válidos: 0 .. N-1 */

    /* Leer ambos vectores y calcular la suma en un solo loop */
    printf("Ingresa los elementos de A y B (par por par):\n");
    for (int i = 0; i < N; i++) {
        printf("a[%d]: ", i);
        scanf("%d", &a[i]);
        printf("b[%d]: ", i);
        scanf("%d", &b[i]);
        c[i] = a[i] + b[i]; /* suma elemento a elemento */
    }

    /* Mostrar el vector resultado */
    printf("\nVector C = A + B:\n");
    for (int i = 0; i < N; i++) {
        printf("c[%d] = %d + %d = %d\n", i, a[i], b[i], c[i]);
    }

    return 0;
}
```

Los tres arreglos tienen el mismo tamaño N y los índices van de 0 a N-1. Nunca accedas a `a[N]`, `b[N]` ni `c[N]` — eso está fuera de los límites.

Muy bien. Solo necesitas llegar hasta la mitad: `i < N/2`. La división entera en C descarta el decimal, así que si N es impar el elemento central queda fuera del loop — no hace falta compararlo consigo mismo. Aquí está el programa corregido y completo:

```c
#include <stdio.h>

int main(void) {
    int N;
    printf("Cuántos caracteres: ");
    scanf("%d", &N);

    char arr[N]; /* índices válidos: 0 .. N-1 */

    /* Loop 1: llenar el arreglo */
    printf("Ingresa los caracteres uno a uno:\n");
    for (int i = 0; i < N; i++) {
        printf("arr[%d]: ", i);
        scanf(" %c", &arr[i]); /* espacio antes de %%c para ignorar espacios/saltos */
    }

    /* Loop 2: verificar palíndromo */
    int es_palindromo = 1; /* asumimos que sí lo es */
    for (int i = 0; i < N / 2; i++) {
        if (arr[i] != arr[N - 1 - i]) { /* comparar con el espejo */
            es_palindromo = 0;
            break; /* con uno que falle ya basta */
        }
    }

    if (es_palindromo) {
        printf("El arreglo ES palíndromo.\n");
    } else {
        printf("El arreglo NO es palíndromo.\n");
    }

    return 0;
}
```

El error clásico es `arr[i] != arr[i]` en lugar de `arr[i] != arr[N-1-i]`. No hay error de compilación — el código simplemente nunca detecta diferencias.

Perfecto. Juntemos todo:

```c
#include <stdio.h>

int main(void) {
    int N;
    printf("Tamaño del arreglo: ");
    scanf("%d", &N);

    int arr[N]; /* índices válidos: 0 .. N-1 */

    /* Loop 1: llenar el arreglo */
    for (int i = 0; i < N; i++) {
        printf("arr[%d]: ", i);
        scanf("%d", &arr[i]);
    }

    int k;
    printf("Posiciones a rotar a la derecha: ");
    scanf("%d", &k);
    k = k % N; /* rotar N veces = no rotar */

    /* Rotar k veces, un paso a la derecha por iteración */
    for (int paso = 0; paso < k; paso++) {
        int temp = arr[N - 1];        /* guardar el último */
        for (int i = N - 2; i >= 0; i--) { /* mover de derecha a izquierda */
            arr[i + 1] = arr[i];
        }
        arr[0] = temp;                /* el último va al principio */
    }

    /* Mostrar resultado */
    printf("\nArreglo rotado %d posición/es a la derecha:\n", k);
    for (int i = 0; i < N; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    return 0;
}
```

El error clásico es intentar mover in-place de izquierda a derecha sin variable temporal — los valores se sobreescriben y se pierden. La variable `temp` y el sentido descendente del loop interno son la solución.

Exactoo. El -1 solo tiene sentido cuando ya sabemos que no está en ningún lugar. Aquí está el programa completo:

```c
#include <stdio.h>

/* Búsqueda lineal: devuelve el índice del valor buscado, o -1 si no existe */
int buscar(int arr[], int N, int valor) {
    for (int i = 0; i < N; i++) {
        if (arr[i] == valor) {
            return i; /* encontrado: retornar posición */
        }
    }
    return -1; /* centinela: no encontrado */
}

int main(void) {
    int N;
    printf("Tamaño del arreglo: ");
    scanf("%d", &N);

    int arr[N]; /* índices válidos: 0 .. N-1 */

    /* Loop: llenar el arreglo */
    for (int i = 0; i < N; i++) {
        printf("arr[%d]: ", i);
        scanf("%d", &arr[i]);
    }

    int valor;
    printf("Valor a buscar: ");
    scanf("%d", &valor);

    int pos = buscar(arr, N, valor);

    if (pos != -1) {
        printf("Encontrado en índice %d.\n", pos);
    } else {
        printf("El valor %d no está en el arreglo.\n", valor);
    }

    return 0;
}
```

La función `buscar` encapsula la lógica de búsqueda. El `return -1` al final solo se alcanza si el loop completo no encontró el valor — ese es el centinela. En `main` siempre verificamos `pos != -1` antes de usarlo como índice.

for (int i = 0; i < M; i++) {
    for (int j = 0; j < N; j++) {
    }
}

Aquí está el programa completo con comentarios:

```c
#include <stdio.h>

#define M 4  /* filas: estudiantes */
#define N 3  /* columnas: materias */

int main(void) {
    int matriz[M][N];

    /* --- Lectura --- */
    printf("Ingresa las calificaciones (fila por fila):\n");
    for (int i = 0; i < M; i++) {          /* recorre filas */
        for (int j = 0; j < N; j++) {      /* recorre columnas */
            printf("Estudiante %d, Materia %d: ", i + 1, j + 1);
            scanf("%d", &matriz[i][j]);    /* i = fila, j = columna */
        }
    }

    /* --- Impresión --- */
    printf("\nTabla de calificaciones:\n");
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            printf("%4d", matriz[i][j]);   /* mismo orden: [i][j] */
        }
        printf("\n");                      /* salto de línea al terminar la fila */
    }

    return 0;
}
```

Punto clave: el ciclo externo siempre controla filas (`i`), el interno siempre controla columnas (`j`). Invertirlos da resultados incorrectos.

