Nítido. Aquí está el programa completo:

```c
#include <stdio.h>

#define M 3  /* vendedores */
#define N 5  /* días de la semana */

int main(void) {
    int ventas[M][N];
    int sumaFila[M];   /* una suma por vendedor */

    /* --- Lectura --- */
    for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            printf("Vendedor %d, Día %d: ", i + 1, j + 1);
            scanf("%d", &ventas[i][j]);
        }
    }

    /* --- Suma por fila --- */
    for (int i = 0; i < M; i++) {
        sumaFila[i] = 0;               /* RESET aquí, dentro del for externo */
        for (int j = 0; j < N; j++) {
            sumaFila[i] += ventas[i][j];
        }
        /* Ya terminé la fila i, puedo imprimir */
        printf("Vendedor %d vendió en total: %d\n", i + 1, sumaFila[i]);
    }

    return 0;
}
```

El error clásico es poner `sumaFila[i] = 0` ANTES del ciclo externo: las sumas de filas anteriores se acumulan en la misma variable. Siempre reinicia el acumulador al entrar a cada fila.

**Ejercicio:** adapta el programa para que además imprima qué vendedor tuvo la mayor venta total. ¡Tú puedes!

int suma = 0;
for (int i = 0; i < N; i++) {
    suma += matriz[i][i];
}

Perfecto. Aquí está el programa completo:

```c
#include <stdio.h>

#define N 4  /* tablero N×N */

int main(void) {
    int tablero[N][N];

    /* --- Lectura --- */
    printf("Ingresa los %d×%d elementos del tablero:\n", N, N);
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            printf("tablero[%d][%d]: ", i, j);
            scanf("%d", &tablero[i][j]);
        }
    }

    /* --- Suma diagonal principal: solo un ciclo --- */
    int suma = 0;
    for (int i = 0; i < N; i++) {
        suma += tablero[i][i];   /* diagonal: fila == columna */
    }

    printf("Suma de la diagonal principal: %d\n", suma);
    return 0;
}
```

La clave: cuando el índice de fila y de columna siempre son iguales, no necesitas ciclos anidados, uno solo basta.

**Ejercicio:** modifica el programa para que también sume la diagonal secundaria (la que va de esquina superior derecha a inferior izquierda). Pista: ¿cuál es la relación entre `i` y `j` en esa diagonal?

