```c
#include <stdio.h>

#define N 3

/* Inicializa el tablero con espacios */
void inicializar(char t[N][N]) {
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            t[i][j] = ' ';
}

/* Imprime el tablero con separadores */
void imprimir(char t[N][N]) {
    printf("\n");
    for (int i = 0; i < N; i++) {
        printf(" %c | %c | %c \n", t[i][0], t[i][1], t[i][2]);
        if (i < N - 1) printf("---+---+---\n");
    }
    printf("\n");
}

/* Devuelve el carácter ganador o ' ' si no hay ganador */
char verificarGanador(char t[N][N]) {
    /* --- Verificar filas --- */
    for (int i = 0; i < N; i++) {
        if (t[i][0] == t[i][1] && t[i][1] == t[i][2] && t[i][0] != ' ')
            return t[i][0];
    }

    /* --- Verificar columnas --- */
    for (int j = 0; j < N; j++) {
        if (t[0][j] == t[1][j] && t[1][j] == t[2][j] && t[0][j] != ' ')
            return t[0][j];
    }

    /* --- Diagonal principal: i == j --- */
    if (t[0][0] == t[1][1] && t[1][1] == t[2][2] && t[0][0] != ' ')
        return t[0][0];

    /* --- Diagonal secundaria: i + j == N-1 --- */
    if (t[0][2] == t[1][1] && t[1][1] == t[2][0] && t[0][2] != ' ')
        return t[0][2];

    return ' ';  /* sin ganador aún */
}

int main(void) {
    char tablero[N][N];
    inicializar(tablero);

    char turno = 'X';
    int jugadas = 0;
    char ganador = ' ';

    printf("=== JUEGO DEL GATO ===\n");
    printf("Ingresa fila y columna (0-2)\n");

    while (ganador == ' ' && jugadas < N * N) {
        imprimir(tablero);
        int fila, col;
        printf("Turno de %c - Fila Columna: ", turno);
        scanf("%d %d", &fila, &col);

        if (fila < 0 || fila >= N || col < 0 || col >= N || tablero[fila][col] != ' ') {
            printf("Movimiento inválido, intenta de nuevo.\n");
            continue;
        }

        tablero[fila][col] = turno;   /* colocar ficha */
        jugadas++;

        ganador = verificarGanador(tablero);
        turno = (turno == 'X') ? 'O' : 'X';  /* cambiar turno */
    }

    imprimir(tablero);

    if (ganador != ' ') {
        printf("¡Ganó el jugador %c! \n", ganador);
    } else {
        printf("¡Empate! Buen juego a los dos.\n");
    }

    return 0;
}
```

Resumen de lo que usamos de arreglos 2D en este juego:
- `tablero[i][j]` para leer y escribir celdas
- Ciclos anidados para inicializar e imprimir
- Condición `i == j` para la diagonal principal
- Condición `i + j == N-1` para la diagonal secundaria

