#include <stdio.h>
#include <stdlib.h>
#include <time.h>

int main() {
    srand(time(NULL));

    int saldo = 100;  // fichas iniciales
    int apuesta;
    int eleccion;    // 1=rojo, 2=negro
    int resultado;   // 1=rojo, 2=negro (aleatorio)
    int continuar;

    printf("Bienvenido al casino. Tienes %d fichas.\n", saldo);

    do {
        printf("\n--- Nueva ronda --- Saldo: %d fichas\n", saldo);

        // Validar apuesta con do-while anidado
        do {
            printf("Cuanto apuestas (1 a %d): ", saldo);
            scanf("%d", &apuesta);
            if (apuesta < 1 || apuesta > saldo) {
                printf("Apuesta invalida. Debe ser entre 1 y %d.\n", saldo);
            }
        } while (apuesta < 1 || apuesta > saldo);  // <-- punto y coma aqui

        printf("Elige: 1=Rojo, 2=Negro: ");
        scanf("%d", &eleccion);

        resultado = rand() % 2 + 1;  // 1 o 2
        printf("La ruleta cayo en: %s\n", resultado == 1 ? "ROJO" : "NEGRO");

        if (eleccion == resultado) {
            saldo += apuesta;
            printf("Ganaste! +%d fichas. Saldo: %d\n", apuesta, saldo);
        } else {
            saldo -= apuesta;
            printf("Perdiste. -%d fichas. Saldo: %d\n", apuesta, saldo);
        }

        if (saldo > 0) {
            printf("Quieres seguir jugando? (1=Si, 0=No): ");
            scanf("%d", &continuar);
        } else {
            continuar = 0;
            printf("Te quedaste sin fichas. Fin del juego.\n");
        }

    } while (saldo > 0 && continuar == 1);  // <-- punto y coma obligatorio aqui

    printf("\nJuego terminado. Fichas finales: %d\n", saldo);

    return 0;
}
```

Fíjate en el `do-while` externo: controla las rondas. El `do-while` interno: valida la apuesta. Cuando el saldo llega a cero, no se pregunta si quiere continuar porque no tiene sentido.

