    if (contador == 0) {
        printf("No hay libros disponibles en este momento.\n");
    } else {
        printf("Total disponibles: %d\n", contador);
    }
}

int main() {
    Libro catalogo[MAX_LIBROS] = {
        {1001, "El Principito",              "Antoine de Saint-Exupéry", true},
        {1002, "Cien años de soledad",       "Gabriel García Márquez",  false},
        {1003, "1984",                        "George Orwell",           true},
        {1004, "Don Quijote de la Mancha",   "Miguel de Cervantes",     false},
        {1005, "Rayuela",                     "Julio Cortázar",          true},
        {1006, "La casa de los espíritus",   "Isabel Allende",          true}
    };

